218			return err
219		}
220	
221		s, err := loadStore(dir)
222		if err != nil {
223			return err
224		}
225		if _, exists := s.Customers[id]; exists {
226			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
227		}
