236	func parsePrice(text string) (int64, error) {
237		text = strings.TrimSpace(text)
238		price, err := strconv.ParseInt(text, 10, 64)
239		if err != nil {
240			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
241		}
242		if price < 0 {
243			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
244		}
245		return price, nil
246	}
