248	// parsedRow 是导入文件中一行解析后的候选用量。
249	type parsedRow struct {
250		line int // 文件中的行号（含表头），用于报错定位
251		rec  usageRecord
252		t    time.Time
253	}
254	
255	func cmdUsageImport(dir, file string) error {
256		var reader io.ReadCloser
257		var source string
258		if file == "-" {
259			reader = io.NopCloser(os.Stdin)
260			source = "标准输入"
261		} else {
262			f, err := os.Open(file)
263			if err != nil {
264				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
265			}
266			reader = f
267			source = file
268		}
269		defer reader.Close()
270	
271		rows, parseErrs := parseUsageFile(reader)
272	
273		s, err := loadStore(dir)
274		if err != nil {
275			return err
276		}
277	
278		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
279		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
280		var problems []string
281		problems = append(problems, parseErrs...)
282	
283		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
284		var ordered []*parsedRow
285		newCount, dupCount := 0, 0
286	
287		for _, r := range rows {
288			cust, ok := s.Customers[r.rec.CustomerID]
289			if !ok {
290				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
291				continue
292			}
293	
294			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
295			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
296			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
297			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
298			var existing *usageRecord
299			if inStore, ok := s.Usage[r.rec.ID]; ok {
300				existing = inStore
301			} else if inBatch, ok := accepted[r.rec.ID]; ok {
302				existing = &inBatch.rec
303			}
304			if existing != nil {
305				if !sameUsage(existing, &r.rec, r.t) {
306					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
307						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
308					continue
309				}
310				dupCount++
311				continue
312			}
313	
314			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
315			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
316			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
317			rowMonth := r.t.UTC().Format("2006-01")
318			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
319				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
320					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
321				continue
322			}
323			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
324			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
325			// 溢出（金额单位：分）。
326			if cust.PlanID == "" {
327				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
328					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
329					continue
330				}
331			} else {
332				rec := r.rec
333				planID := s.effectivePlanID(cust, rowMonth)
334				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
335					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
336					continue
337				}
338			}
339	
340			// 全新标识：不得进入该客户已封账的 UTC 自然月。
341			if s.sealed(r.rec.CustomerID, rowMonth) {
342				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
343					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
344				continue
345			}
346	
347			rr := r
348			accepted[r.rec.ID] = rr
349			ordered = append(ordered, rr)
350			newCount++
351		}
352	
353		if len(problems) > 0 {
354			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
355		}
356	
357		for _, r := range ordered {
358			rec := r.rec
359			s.Usage[rec.ID] = &rec
360		}
361		if err := s.save(); err != nil {
362			return err
363		}
364		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
365		return nil
366	}
