368	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
369	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
370		cr := csv.NewReader(r)
371		cr.FieldsPerRecord = 4
372		cr.TrimLeadingSpace = true
373	
374		header, err := cr.Read()
375		if err == io.EOF {
376			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
377		}
378		if err != nil {
379			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
380		}
381		for i := range header {
382			header[i] = strings.TrimSpace(header[i])
383		}
384		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
385			header[2] != "time" || header[3] != "quantity" {
386			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
387		}
388	
389		var rows []*parsedRow
390		var problems []string
391		line := 1
392		for {
393			rec, err := cr.Read()
394			if err == io.EOF {
395				break
396			}
397			line++
398			if err != nil {
399				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
400				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
401					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
402					break
403				}
404				continue
405			}
406			for i := range rec {
407				rec[i] = strings.TrimSpace(rec[i])
408			}
409	
410			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
411			if id == "" {
412				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
413				continue
414			}
415			if custID == "" {
416				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
417				continue
418			}
419			t, err := time.Parse(time.RFC3339, ts)
420			if err != nil {
421				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
422				continue
423			}
424			qty, err := strconv.ParseInt(qtyText, 10, 64)
425			if err != nil {
426				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
427				continue
428			}
429			if qty <= 0 {
430				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
431				continue
432			}
433	
434			rows = append(rows, &parsedRow{
435				line: line,
436				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
437				t:    t,
438			})
439		}
440		return rows, problems
441	}
