443	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
444	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
445	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
446		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
447			return false
448		}
449		et, err := time.Parse(time.RFC3339, existing.Time)
450		if err != nil {
451			return existing.Time == candidate.Time
452		}
453		return et.Equal(candidateT)
454	}
