456	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
457	func validMonth(m string) bool {
458		t, err := time.Parse("2006-01", m)
459		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
460			return false
461		}
462		return true
463	}
464	
465	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
466	func inMonth(rfc3339, month string) bool {
467		t, err := time.Parse(time.RFC3339, rfc3339)
468		if err != nil {
469			return false
470		}
471		return t.UTC().Format("2006-01") == month
472	}
473	
474	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
475	// 入参时间均已在载入/导入时校验为 RFC3339。
476	func utcMonth(rfc3339 string) string {
477		t, _ := time.Parse(time.RFC3339, rfc3339)
478		return t.UTC().Format("2006-01")
479	}
