481	func cmdBillSettle(dir, customerID, month string) error {
482		if !validMonth(month) {
483			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
484		}
485		s, err := loadStore(dir)
486		if err != nil {
487			return err
488		}
489		cust, ok := s.Customers[customerID]
490		if !ok {
491			return fmt.Errorf("客户标识 %q 不存在", customerID)
492		}
493	
494		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
495		if s.isSuspendedMonth(customerID, month) {
496			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
497		}
498	
499		key := billKey(customerID, month)
500		if existing, ok := s.Bills[key]; ok {
501			// 幂等：同一客户同一月份重复结算，直接返回原账单，
502			// 不重新计费、不产生新账单或调整、不落盘。
503			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
504			printBill(existing, cust, s)
505			return nil
506		}
507	
508		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
509		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
510		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
511		// 结算且不封账。
512		inMonthRecs := monthUsage(s, customerID, month)
513		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
514			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
515		}
516	
517		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
518		if cust.PlanID != "" {
519			return settleTiered(s, cust, month, inMonthRecs)
520		}
521	
522		b, err := buildFixedBill(cust, month, inMonthRecs)
523		if err != nil {
524			return fmt.Errorf("%v，拒绝结算且不封账", err)
525		}
526		s.Bills[key] = b
527	
528		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
529		if err := s.save(); err != nil {
530			delete(s.Bills, key)
531			return err
532		}
533		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
534		printBill(b, cust, s)
535		return nil
536	}
