558	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
559	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
560	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
561	// 记录按原有时间点及标识顺序从零累计重新分档。
562	func monthUsage(s *state, customerID, month string) []*usageRecord {
563		var recs []*usageRecord
564		for _, u := range s.Usage {
565			if s.isWithdrawn(u.ID) {
566				continue
567			}
568			if u.CustomerID == customerID && inMonth(u.Time, month) {
569				recs = append(recs, u)
570			}
571		}
572		sortByInstant(recs)
573		return recs
574	}
