576	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
577	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
578	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
579		lines := make([]billLine, 0, len(recs))
580		var totalQty, totalFee int64
581		for _, u := range recs {
582			lineFee, err := mul64(u.Quantity, cust.Price)
583			if err != nil {
584				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
585			}
586			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
587				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
588			}
589			if totalFee, err = add64(totalFee, lineFee); err != nil {
590				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
591			}
592			lines = append(lines, billLine{
593				UsageID:  u.ID,
594				Time:     u.Time,
595				Quantity: u.Quantity,
596				LineFee:  lineFee,
597			})
598		}
599		return &bill{
600			ID:         stableBillID(cust.ID, month),
601			CustomerID: cust.ID,
602			Month:      month,
603			TotalQty:   totalQty,
604			UnitPrice:  cust.Price,
605			TotalFee:   totalFee,
606			Lines:      lines,
607			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
608		}, nil
609	}
