611	func sortByInstant(us []*usageRecord) {
612		// 入参时间均已在载入/导入时校验为 RFC3339。
613		sort.Slice(us, func(i, j int) bool {
614			ti, _ := time.Parse(time.RFC3339, us[i].Time)
615			tj, _ := time.Parse(time.RFC3339, us[j].Time)
616			ui, uj := ti.UTC(), tj.UTC()
617			if !ui.Equal(uj) {
618				return ui.Before(uj)
619			}
620			return us[i].ID < us[j].ID
621		})
622	}
