624	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
625	func stableBillID(customerID, month string) string {
626		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
627		return "BILL-" + hex.EncodeToString(sum[:])[:16]
628	}
