630	func printBill(b *bill, cust *customer, s *state) {
631		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
632		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
633		// 涉及该月即纳入，即使后来被更正移出。
634		pays := paymentsEverFor(s, b.CustomerID, b.Month)
635		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
636		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
637		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
638		tiered := b.Pricing == "tiered"
639		if tiered {
640			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
641			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
642			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
643			fmt.Fprintln(stdout, "阶梯规则：")
644			for i, t := range b.PlanTiers {
645				if t.Limit == 0 {
646					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
647				} else {
648					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
649				}
650			}
651		} else {
652			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
653		}
654		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
655		if tiered {
656			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
657			// 月费不计入总数量、各档金额或逐条小计。
658			usageFee := b.TotalFee - b.MonthlyFee
659			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
660			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
661			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
662		} else {
663			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
664		}
665		if tiered {
666			fmt.Fprintln(stdout, "各档合计：")
667			for i, tt := range b.TierTotals {
668				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
669					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
670			}
671		}
672		// 数据在载入时已校验一致，此处计算不会出错。
673		net, payable, _ := billTotals(b, adjs)
674		received, _ := paymentReceived(s, b.CustomerID, b.Month)
675		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
676		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
677		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
678		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
679		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
680		if len(b.Lines) == 0 {
681			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
682		} else {
683			fmt.Fprintln(stdout, "明细：")
684		}
685		for i, ln := range b.Lines {
686			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
687				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
688			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
689			for j, seg := range ln.Segments {
690				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
691					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
692			}
693		}
694		if len(adjs) == 0 {
695			fmt.Fprintln(stdout, "调整与撤销历史：无")
696		} else {
697			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
698			for i, ev := range historyEvents(adjs) {
699				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
700			}
701		}
702		if len(pays) == 0 {
703			fmt.Fprintln(stdout, "收款与撤销历史：无")
704		} else {
705			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
706			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
707				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
708			}
709		}
710	}
