712	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
713	func historyEvents(adjs []*adjustment) []string {
714		type event struct {
715			seq  int64
716			text string
717		}
718		var events []event
719		for _, a := range adjs {
720			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
721				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
722			if a.Revoked {
723				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
724					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
725			}
726		}
727		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
728		out := make([]string, len(events))
729		for i, ev := range events {
730			out[i] = ev.text
731		}
732		return out
733	}
734	
735	func adjustKind(amount int64) string {
736		if amount > 0 {
737			return "补收"
738		}
739		return "减免"
740	}
741	
742	func adjustStatus(a *adjustment) string {
743		if a.Revoked {
744			return "已撤销"
745		}
746		return "生效中"
747	}
748	
749	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
750	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
751	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
752	// 的最新分配。
753	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
754		type event struct {
755			seq  int64
756			text string
757		}
758		var events []event
759		for _, p := range pays {
760			alloc := p.amountFor(month)
761			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
762				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
763			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
764			running := alloc
765			for _, c := range correctionsFor(s, p.ID) {
766				after := allocAmountFor(c.Allocations, month)
767				if running == 0 && after == 0 {
768					continue // 本次更正不涉及本账单
769				}
770				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
771					c.ID, c.Reason, p.ID, running, after)})
772				running = after
773			}
774			if p.Revoked {
775				// 整笔撤销取消的是撤销时的最新分配。
776				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
777					p.ID, p.RevokeReason, p.ID, p.Total, running)})
778			}
779		}
780		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
781		out := make([]string, len(events))
782		for i, ev := range events {
783			out[i] = ev.text
784		}
785		return out
786	}
