808	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
809		if !validMonth(month) {
810			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
811		}
812		if strings.TrimSpace(adjID) == "" {
813			return fmt.Errorf("调整标识不能为空")
814		}
815		amount, err := parseAmount(amountText)
816		if err != nil {
817			return err
818		}
819		if strings.TrimSpace(reason) == "" {
820			return fmt.Errorf("调整原因不能为空")
821		}
822	
823		s, err := loadStore(dir)
824		if err != nil {
825			return err
826		}
827		if _, ok := s.Customers[customerID]; !ok {
828			return fmt.Errorf("客户标识 %q 不存在", customerID)
829		}
830		b, ok := s.Bills[billKey(customerID, month)]
831		if !ok {
832			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
833		}
834	
835		if existing, ok := s.Adjustments[adjID]; ok {
836			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
837			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
838			if existing.CustomerID == customerID && existing.Month == month &&
839				existing.Amount == amount && existing.Reason == reason {
840				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
841				printAdjustment(existing, s)
842				return nil
843			}
844			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
845				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
846		}
847	
848		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
849		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
850		// 不占用该调整标识。
851		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
852		if err != nil {
853			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
854		}
855		received, err := paymentReceived(s, customerID, month)
856		if err != nil {
857			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
858		}
859		newPayable, err := addSigned64(payable, amount)
860		if err != nil {
861			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
862		}
863		if newPayable < 0 {
864			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
865		}
866		if newPayable < received {
867			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
868				newPayable, received, payable, amount)
869		}
870	
871		a := &adjustment{
872			ID:         adjID,
873			CustomerID: customerID,
874			Month:      month,
875			Amount:     amount,
876			Reason:     reason,
877			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
878		}
879		s.NextSeq++
880		a.Seq = s.NextSeq
881		s.Adjustments[adjID] = a
882	
883		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
884		// 该调整标识不被占用。
885		if err := s.save(); err != nil {
886			delete(s.Adjustments, adjID)
887			s.NextSeq--
888			return err
889		}
890		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
891			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
892		printAdjustment(a, s)
893		return nil
894	}
