896	func cmdBillRevoke(dir, adjID, reason string) error {
897		if strings.TrimSpace(adjID) == "" {
898			return fmt.Errorf("调整标识不能为空")
899		}
900		if strings.TrimSpace(reason) == "" {
901			return fmt.Errorf("撤销原因不能为空")
902		}
903	
904		s, err := loadStore(dir)
905		if err != nil {
906			return err
907		}
908		a, ok := s.Adjustments[adjID]
909		if !ok {
910			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
911		}
912	
913		if a.Revoked {
914			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
915			// 改用其他原因则拒绝。
916			if a.RevokeReason == reason {
917				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
918				printAdjustment(a, s)
919				return nil
920			}
921			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
922		}
923	
924		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
925		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
926		// 改变余额后重试。
927		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
928		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
929		if err != nil {
930			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
931		}
932		received, err := paymentReceived(s, a.CustomerID, a.Month)
933		if err != nil {
934			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
935		}
936		neg, err := neg64(a.Amount)
937		if err != nil {
938			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
939		}
940		newPayable, err := addSigned64(payable, neg)
941		if err != nil {
942			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
943				payable, a.Amount)
944		}
945		if newPayable < 0 {
946			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
947				newPayable, payable, a.Amount)
948		}
949		if newPayable < received {
950			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
951				newPayable, received, payable, a.Amount)
952		}
953	
954		a.Revoked = true
955		a.RevokeReason = reason
956		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
957		s.NextSeq++
958		a.RevokeSeq = s.NextSeq
959	
960		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
961		if err := s.save(); err != nil {
962			a.Revoked = false
963			a.RevokeReason = ""
964			a.RevokedAt = ""
965			a.RevokeSeq = 0
966			s.NextSeq--
967			return err
968		}
969		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
970			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
971		printAdjustment(a, s)
972		return nil
973	}
