1018	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1019		total, err := parsePositiveAmount(totalText)
1020		if err != nil {
1021			return err
1022		}
1023		allocs, err := parseAllocations(allocArgs)
1024		if err != nil {
1025			return err
1026		}
1027		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1028		var sum int64
1029		for _, al := range allocs {
1030			sum, err = add64(sum, al.Amount)
1031			if err != nil {
1032				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1033			}
1034		}
1035		if sum != total {
1036			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1037		}
1038		return registerPayment(dir, customerID, payID, total, note, allocs)
1039	}
1040	
1041	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1042	// 月份不得重复，每项金额为正整数分。
1043	func parseAllocations(args []string) ([]paymentAllocation, error) {
1044		if len(args) == 0 {
1045			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1046		}
1047		seen := make(map[string]bool)
1048		allocs := make([]paymentAllocation, 0, len(args))
1049		for _, arg := range args {
1050			parts := strings.Split(arg, ":")
1051			if len(parts) != 2 {
1052				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1053			}
1054			month := strings.TrimSpace(parts[0])
1055			if !validMonth(month) {
1056				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1057			}
1058			if seen[month] {
1059				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1060			}
1061			seen[month] = true
1062			amount, err := parsePositiveAmount(parts[1])
1063			if err != nil {
1064				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1065			}
1066			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1067		}
1068		return allocs, nil
1069	}
1070	
1071	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1072	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1073	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1074		if strings.TrimSpace(payID) == "" {
1075			return fmt.Errorf("收款标识不能为空")
1076		}
1077		if strings.TrimSpace(note) == "" {
1078			return fmt.Errorf("收款备注不能为空")
1079		}
1080		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1081		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1082	
1083		s, err := loadStore(dir)
1084		if err != nil {
1085			return err
1086		}
1087		if _, ok := s.Customers[customerID]; !ok {
1088			return fmt.Errorf("客户标识 %q 不存在", customerID)
1089		}
1090		for _, al := range allocs {
1091			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1092				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1093			}
1094		}
1095	
1096		if existing, ok := s.Payments[payID]; ok {
1097			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1098			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1099			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1100			if samePaymentContent(existing, customerID, total, note, allocs) {
1101				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1102				printPayment(existing, s)
1103				return nil
1104			}
1105			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1106				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1107		}
1108	
1109		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1110		for _, al := range allocs {
1111			b := s.Bills[billKey(customerID, al.Month)]
1112			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1113			if err != nil {
1114				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1115			}
1116			received, err := paymentReceived(s, customerID, al.Month)
1117			if err != nil {
1118				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1119			}
1120			if payable == 0 {
1121				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1122			}
1123			if al.Amount > payable-received {
1124				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1125					al.Amount, payable-received, customerID, al.Month, payable, received)
1126			}
1127		}
1128	
1129		p := &payment{
1130			ID:          payID,
1131			CustomerID:  customerID,
1132			Total:       total,
1133			Note:        note,
1134			Allocations: allocs,
1135			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1136		}
1137		s.NextSeq++
1138		p.Seq = s.NextSeq
1139		s.Payments[payID] = p
1140	
1141		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1142		// 一切不生效，该收款标识不被占用。
1143		if err := s.save(); err != nil {
1144			delete(s.Payments, payID)
1145			s.NextSeq--
1146			return err
1147		}
1148		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1149		printAllocationBalances(s, p, allocs)
1150		fmt.Fprintln(stdout)
1151		printPayment(p, s)
1152		return nil
1153	}
1154	
1155	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1156	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1157	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1158		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1159			return false
1160		}
1161		return sameAllocations(p.Allocations, allocs)
1162	}
1163	
1164	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1165	func sameAllocations(a, b []paymentAllocation) bool {
1166		if len(a) != len(b) {
1167			return false
1168		}
1169		for _, al := range b {
1170			if allocAmountFor(a, al.Month) != al.Amount {
1171				return false
1172			}
1173		}
1174		return true
1175	}
1176	
1177	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1178	func formatAllocations(allocs []paymentAllocation) string {
1179		parts := make([]string, len(allocs))
1180		for i, al := range allocs {
1181			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1182		}
1183		return strings.Join(parts, ",")
1184	}
1185	
1186	// printAllocationBalances 输出给定分配列表每个分配月份当前的实收与未收余额。
1187	func printAllocationBalances(s *state, p *payment, allocs []paymentAllocation) {
1188		for _, al := range allocs {
1189			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1190			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1191			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1192			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
1193				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
1194		}
1195	}
