1197	func cmdBillUnpay(dir, payID, reason string) error {
1198		if strings.TrimSpace(payID) == "" {
1199			return fmt.Errorf("收款标识不能为空")
1200		}
1201		if strings.TrimSpace(reason) == "" {
1202			return fmt.Errorf("撤销原因不能为空")
1203		}
1204	
1205		s, err := loadStore(dir)
1206		if err != nil {
1207			return err
1208		}
1209		p, ok := s.Payments[payID]
1210		if !ok {
1211			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1212		}
1213	
1214		if p.Revoked {
1215			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1216			// 改用其他原因则拒绝。
1217			if p.RevokeReason == reason {
1218				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1219				printPayment(p, s)
1220				return nil
1221			}
1222			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1223		}
1224	
1225		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1226		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1227		// 分配、更正与撤销原因永久保留。
1228		p.Revoked = true
1229		p.RevokeReason = reason
1230		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1231		s.NextSeq++
1232		p.RevokeSeq = s.NextSeq
1233	
1234		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1235		if err := s.save(); err != nil {
1236			p.Revoked = false
1237			p.RevokeReason = ""
1238			p.RevokedAt = ""
1239			p.RevokeSeq = 0
1240			s.NextSeq--
1241			return err
1242		}
1243		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1244		printAllocationBalances(s, p, currentAllocations(s, p))
1245		fmt.Fprintln(stdout)
1246		printPayment(p, s)
1247		return nil
1248	}
