1277	// --- 收款分配更正 ---
1278	
1279	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1280		if strings.TrimSpace(payID) == "" {
1281			return fmt.Errorf("收款标识不能为空")
1282		}
1283		if strings.TrimSpace(corrID) == "" {
1284			return fmt.Errorf("更正标识不能为空")
1285		}
1286		if strings.TrimSpace(reason) == "" {
1287			return fmt.Errorf("更正原因不能为空")
1288		}
1289		allocs, err := parseAllocations(allocArgs)
1290		if err != nil {
1291			return err
1292		}
1293		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1294		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1295	
1296		s, err := loadStore(dir)
1297		if err != nil {
1298			return err
1299		}
1300		p, ok := s.Payments[payID]
1301		if !ok {
1302			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1303		}
1304	
1305		if existing, ok := s.Corrections[corrID]; ok {
1306			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1307			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1308			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1309			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1310				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1311				printCorrection(existing, s)
1312				return nil
1313			}
1314			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1315				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1316		}
1317	
1318		// 新增更正只允许未撤销收款。
1319		if p.Revoked {
1320			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1321		}
1322	
1323		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1324		var sum int64
1325		for _, al := range allocs {
1326			sum, err = add64(sum, al.Amount)
1327			if err != nil {
1328				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1329			}
1330		}
1331		if sum != p.Total {
1332			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1333		}
1334		// 新分配月份须是原客户的已结算账单。
1335		for _, al := range allocs {
1336			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1337				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1338			}
1339		}
1340	
1341		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1342		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1343		current := currentAllocations(s, p)
1344		for _, m := range unionMonths(current, allocs) {
1345			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1346			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1347			if err != nil {
1348				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1349			}
1350			received, err := paymentReceived(s, p.CustomerID, m)
1351			if err != nil {
1352				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1353			}
1354			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1355			received -= allocAmountFor(current, m)
1356			received, err = add64(received, allocAmountFor(allocs, m))
1357			if err != nil {
1358				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1359			}
1360			if received > payable {
1361				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1362					p.CustomerID, m, received, payable)
1363			}
1364		}
1365	
1366		c := &correction{
1367			ID:          corrID,
1368			PaymentID:   payID,
1369			Reason:      reason,
1370			Allocations: allocs,
1371			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1372		}
1373		s.NextSeq++
1374		c.Seq = s.NextSeq
1375		s.Corrections[corrID] = c
1376	
1377		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1378		// 一切不生效，该更正标识不被占用。
1379		if err := s.save(); err != nil {
1380			delete(s.Corrections, corrID)
1381			s.NextSeq--
1382			return err
1383		}
1384		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1385		printCorrection(c, s)
1386		return nil
1387	}
1388	
1389	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1390	func unionMonths(a, b []paymentAllocation) []string {
1391		set := make(map[string]bool, len(a)+len(b))
1392		for _, al := range a {
1393			set[al.Month] = true
1394		}
1395		for _, al := range b {
1396			set[al.Month] = true
1397		}
1398		months := make([]string, 0, len(set))
1399		for m := range set {
1400			months = append(months, m)
1401		}
1402		sort.Strings(months)
1403		return months
1404	}
1405	
1406	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1407	// 新分配，或（首次更正时）收款的原始分配。
1408	func allocationBefore(s *state, c *correction) []paymentAllocation {
1409		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1410		var latest *correction
1411		for _, o := range s.Corrections {
1412			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1413				latest = o
1414			}
1415		}
1416		if latest != nil {
1417			before = latest.Allocations
1418		}
1419		return before
1420	}
1421	
1422	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1423	// 以及前后分配涉及月份的当前余额。
1424	func printCorrection(c *correction, s *state) {
1425		p := s.Payments[c.PaymentID] // 载入时已校验存在
1426		before := allocationBefore(s, c)
1427		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1428		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1429			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1430		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1431		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1432		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1433		fmt.Fprintln(stdout, "涉及月份当前余额：")
1434		for _, m := range unionMonths(before, c.Allocations) {
1435			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1436			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1437			received, _ := paymentReceived(s, p.CustomerID, m)
1438			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1439				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1440				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1441		}
1442	}
1443	
1444	// --- 账后对账流水 ---
1445	
1446	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1447	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1448	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1449	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1450	type ledgerEvent struct {
1451		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1452		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1453		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1454		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1455		deltaReceived int64  // 对实收的影响（分，带符号）
1456		note          string // 原因（调整/更正类）或备注（收款类）
1457		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1458		payTotal      int64  // 收款类事件：汇款总额
1459		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1460		payID         string // 更正事件：关联收款标识
1461		beforeAlloc   int64  // 更正事件：本账单更正前分配
1462		afterAlloc    int64  // 更正事件：本账单更正后分配
1463		afterPayable  int64  // 事件后的应付（回放时填充）
1464		afterReceived int64  // 事件后的实收（回放时填充）
1465	}
1466	
1467	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1468	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1469	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1470	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1471	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1472	// 只读：不修改库、不占用序号、不新增记录。
1473	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1474		var events []ledgerEvent
1475		for _, a := range s.Adjustments {
1476			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1477				continue
1478			}
1479			events = append(events, ledgerEvent{
1480				seq: a.Seq, kind: "调整", refID: a.ID,
1481				deltaPayable: a.Amount, note: a.Reason,
1482			})
1483			if a.Revoked {
1484				neg, err := neg64(a.Amount)
1485				if err != nil {
1486					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1487				}
1488				events = append(events, ledgerEvent{
1489					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1490					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1491				})
1492			}
1493		}
1494		for _, p := range s.Payments {
1495			if p.CustomerID != b.CustomerID {
1496				continue
1497			}
1498			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1499			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1500			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1501			alloc := p.amountFor(b.Month)
1502			corrs := correctionsFor(s, p.ID)
1503			involved := alloc > 0
1504			if !involved {
1505				for _, c := range corrs {
1506					if allocAmountFor(c.Allocations, b.Month) > 0 {
1507						involved = true
1508						break
1509					}
1510				}
1511			}
1512			if !involved {
1513				continue
1514			}
1515			if alloc > 0 {
1516				events = append(events, ledgerEvent{
1517					seq: p.Seq, kind: "收款", refID: p.ID,
1518					deltaReceived: alloc, note: p.Note,
1519					payTotal: p.Total, payAlloc: alloc,
1520				})
1521			}
1522			running := alloc
1523			for _, c := range corrs {
1524				after := allocAmountFor(c.Allocations, b.Month)
1525				if running == 0 && after == 0 {
1526					continue // 本次更正不涉及本账单
1527				}
1528				events = append(events, ledgerEvent{
1529					seq: c.Seq, kind: "更正", refID: c.ID,
1530					deltaReceived: after - running, note: c.Reason,
1531					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1532				})
1533				running = after
1534			}
1535			if p.Revoked {
1536				events = append(events, ledgerEvent{
1537					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1538					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1539					payTotal: p.Total, payAlloc: running,
1540				})
1541			}
1542		}
1543		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1544	
1545		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1546		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1547		// 仍能成功。
1548		payable := b.TotalFee
1549		var received int64
1550		seen := make(map[int64]string, len(events))
1551		for i := range events {
1552			ev := &events[i]
1553			desc := ev.kind + " " + ev.refID
1554			if prev, dup := seen[ev.seq]; dup {
1555				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1556			}
1557			seen[ev.seq] = desc
1558			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1559				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1560			}
1561			var err error
1562			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1563				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1564			}
1565			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1566				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1567			}
1568			if payable < 0 {
1569				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1570			}
1571			if received < 0 {
1572				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1573			}
1574			if received > payable {
1575				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1576			}
1577			ev.afterPayable = payable
1578			ev.afterReceived = received
1579		}
1580		return events, nil
1581	}
1582	
1583	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1584		if !validMonth(month) {
1585			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1586		}
1587		s, err := loadStore(dir)
1588		if err != nil {
1589			return err
1590		}
1591		cust, ok := s.Customers[customerID]
1592		if !ok {
1593			return fmt.Errorf("客户标识 %q 不存在", customerID)
1594		}
1595		b, ok := s.Bills[billKey(customerID, month)]
1596		if !ok {
1597			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1598		}
1599	
1600		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1601		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1602		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1603		cutoff := s.NextSeq
1604		cutoffDesc := "省略，按最新"
1605		if hasCutoff {
1606			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1607			if perr != nil {
1608				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1609			}
1610			if v < 0 {
1611				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1612			}
1613			if v > s.NextSeq {
1614				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1615			}
1616			cutoff = v
1617			cutoffDesc = "指定"
1618		}
1619	
1620		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1621		// 拒绝，不输出部分正常的报告。
1622		events, err := billLedger(s, b)
1623		if err != nil {
1624			return err
1625		}
1626		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1627		return nil
1628	}
1629	
1630	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1631		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1632		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1633		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1634		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1635		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1636		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1637		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1638			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1639	
1640		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1641		payable, received := b.TotalFee, int64(0)
1642		var shown []ledgerEvent
1643		for _, ev := range events {
1644			if ev.seq > cutoff {
1645				continue
1646			}
1647			shown = append(shown, ev)
1648			payable, received = ev.afterPayable, ev.afterReceived
1649		}
1650		if len(shown) == 0 {
1651			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1652		} else {
1653			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1654			for i, ev := range shown {
1655				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1656			}
1657		}
1658		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1659			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1660	}
1661	
1662	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1663	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1664	// 说明汇款总额与本账单分配。
1665	func formatLedgerEvent(ev ledgerEvent) string {
1666		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1667			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1668		switch ev.kind {
1669		case "调整":
1670			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1671				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1672		case "撤销调整":
1673			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1674				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1675		case "收款":
1676			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1677				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1678		case "更正":
1679			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1680				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1681		default: // 撤销收款
1682			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1683				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1684		}
1685	}
1686

