1	package main
2	
3	import (
4		"fmt"
5		"sort"
6		"strconv"
7		"strings"
8	)
9	
10	// --- 客户跨账期对账报表 ---
11	//
12	// bill reconcile 用一份只读报表核对一个客户在一段账后操作（全局操作序号
13	// 区间）内、多个账期（包含首尾的 YYYY-MM 范围）的余额变化：只选择范围内
14	// 当前已存在的账单（不补结算、不按操作时间筛选），各账单在序号 0 以原总
15	// 金额为应付、零实收起算；起止余额分别取对应序号操作完成后的状态，变动
16	// 区间为起点之后、终点以内。逐月两端余额与相同截止的 bill ledger 一致，
17	// 终点为存档最新序号时与 bill show 一致。
18	
19	// reconBill 是报表选中的一张账单及其在起止序号后的余额。
20	type reconBill struct {
21		b         *bill
22		startPay  int64 // 起点序号完成后的应付
23		startRecv int64 // 起点序号完成后的实收
24		endPay    int64 // 终点序号完成后的应付
25		endRecv   int64 // 终点序号完成后的实收
26	}
27	
28	// reconMonthChange 是一次账后操作对范围内某一个账期的金额影响。
29	type reconMonthChange struct {
30		month         string
31		deltaPayable  int64 // 对应付的影响（分，带符号）
32		deltaReceived int64 // 对实收的影响（分，带符号）
33		alloc         int64 // 收款：登记分配；撤销收款：被取消的最新分配
34		beforeAlloc   int64 // 更正：更正前分配
35		afterAlloc    int64 // 更正：更正后分配
36	}
37	
38	// reconEvent 是报表中合并展示的一次账后操作：调整、撤销调整、收款、
39	// 分配更正或撤销收款。每次操作只出现一次，范围内各月的变化合并在同一
40	// 条目下；同名的调整、收款与更正标识属于不同类型的记录，按类型区分，
41	// 互不混淆。
42	type reconEvent struct {
43		seq       int64
44		kind      string // 调整 / 撤销调整 / 收款 / 更正 / 撤销收款
45		refID     string // 记录标识（调整、收款或更正标识）
46		note      string // 原因（调整/更正/撤销类）或备注（收款）
47		linkSeq   int64  // 撤销事件关联的原操作序号；非撤销为 0
48		payTotal  int64  // 收款类事件：汇款总额
49		payID     string // 更正事件：关联收款标识
50		changes   []reconMonthChange
51		afterPay  int128 // 事件后范围内汇总应付（回放时填充）
52		afterRecv int128 // 事件后范围内汇总实收（回放时填充）
53	}
54	
55	func cmdBillReconcile(dir, customerID, startMonth, endMonth string, seqArgs []string) error {
56		if !validMonth(startMonth) {
57			return fmt.Errorf("起始账期 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", startMonth)
58		}
59		if !validMonth(endMonth) {
60			return fmt.Errorf("截止账期 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", endMonth)
61		}
62		if endMonth < startMonth {
63			return fmt.Errorf("起始账期 %s 晚于截止账期 %s，账期范围包含首尾且起月不得晚于止月", startMonth, endMonth)
64		}
65	
66		s, err := loadStore(dir)
67		if err != nil {
68			return err
69		}
70		cust, ok := s.Customers[customerID]
71		if !ok {
72			return fmt.Errorf("客户标识 %q 不存在", customerID)
73		}
74	
75		// 起止操作序号使用调整/收款/更正及其撤销共用的已保存全局序号：省略表示
76		// 0 至存档最新序号；须满足 0 ≤ 起点 ≤ 终点 ≤ 存档全局序号上限，因其他
77		// 客户或月份操作造成的序号空档合法。
78		startSeq, endSeq := int64(0), s.NextSeq
79		seqDesc := "省略，按 0 至存档最新序号"
80		if len(seqArgs) == 2 {
81			from, err := parseReconSeq(seqArgs[0], "起始操作序号")
82			if err != nil {
83				return err
84			}
85			to, err := parseReconSeq(seqArgs[1], "截止操作序号")
86			if err != nil {
87				return err
88			}
89			if from > to {
90				return fmt.Errorf("起始操作序号 %d 晚于截止操作序号 %d，须满足 0 ≤ 起点 ≤ 终点", from, to)
91			}
92			if to > s.NextSeq {
93				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", to, s.NextSeq)
94			}
95			startSeq, endSeq = from, to
96			seqDesc = "指定"
97		}
98	
99		// 只选择该客户账期范围内当前已存在的账单，不补结算、不按操作时间筛选。
100		var months []string
101		for _, b := range s.Bills {
102			if b.CustomerID == customerID && b.Month >= startMonth && b.Month <= endMonth {
103				months = append(months, b.Month)
104			}
105		}
106		sort.Strings(months)
107	
108		// 输出前核验所有选中账单的完整流水：任何异常（即使发生在终点序号之后）
109		// 都拒绝，不输出部分报表。逐月两端余额取自同一批已核验流水，与相同截止
110		// 序号的 bill ledger 一致。
111		bills := make([]reconBill, 0, len(months))
112		for _, m := range months {
113			b := s.Bills[billKey(customerID, m)]
114			events, err := billLedger(s, b)
115			if err != nil {
116				return err
117			}
118			rb := reconBill{b: b}
119			rb.startPay, rb.startRecv = ledgerBalanceAt(b, events, startSeq)
120			rb.endPay, rb.endRecv = ledgerBalanceAt(b, events, endSeq)
121			bills = append(bills, rb)
122		}
123	
124		ops, err := reconcileEvents(s, customerID, startMonth, endMonth, startSeq, endSeq)
125		if err != nil {
126			return err
127		}
128	
129		// 汇总以 128 位整数精确累加：单账单余额保证在有符号 64 位内，多账单
130		// 合计可能超出有符号 64 位上限，仍须精确输出。
131		sumOrig := int128Of(0)
132		startPaySum, startRecvSum := int128Of(0), int128Of(0)
133		endPaySum, endRecvSum := int128Of(0), int128Of(0)
134		for _, rb := range bills {
135			sumOrig = sumOrig.add(int128Of(rb.b.TotalFee))
136			startPaySum = startPaySum.add(int128Of(rb.startPay))
137			startRecvSum = startRecvSum.add(int128Of(rb.startRecv))
138			endPaySum = endPaySum.add(int128Of(rb.endPay))
139			endRecvSum = endRecvSum.add(int128Of(rb.endRecv))
140		}
141	
142		// 回放区间内操作，填充每次操作后的范围内汇总余额。
143		curPay, curRecv := startPaySum, startRecvSum
144		for i := range ops {
145			for _, ch := range ops[i].changes {
146				curPay = curPay.add(int128Of(ch.deltaPayable))
147				curRecv = curRecv.add(int128Of(ch.deltaReceived))
148			}
149			ops[i].afterPay, ops[i].afterRecv = curPay, curRecv
150		}
151		// 操作变化与逐月余额来自同一批已核验流水，终点处必然一致。
152		if curPay != endPaySum || curRecv != endRecvSum {
153			return fmt.Errorf("区间内操作汇总与逐月终点余额不一致，数据异常，拒绝输出报表")
154		}
155	
156		printReconcile(cust, startMonth, endMonth, startSeq, endSeq, seqDesc, s.NextSeq,
157			bills, sumOrig, startPaySum, startRecvSum, endPaySum, endRecvSum, ops)
158		return nil
159	}
160	
161	// parseReconSeq 解析操作序号：非负有符号 64 位整数。
162	func parseReconSeq(text, name string) (int64, error) {
163		v, err := strconv.ParseInt(strings.TrimSpace(text), 10, 64)
164		if err != nil {
165			return 0, fmt.Errorf("%s %q 不是非负整数: %w", name, text, err)
166		}
167		if v < 0 {
168			return 0, fmt.Errorf("%s不能为负数，收到 %d", name, v)
169		}
170		return v, nil
171	}
172	
173	// ledgerBalanceAt 返回账单在指定操作序号完成后的应付与实收：序号 0 以原
174	// 总金额为应付、零实收起算，与 bill ledger 相同截止的余额一致。
175	func ledgerBalanceAt(b *bill, events []ledgerEvent, seq int64) (payable, received int64) {
176		payable, received = b.TotalFee, 0
177		for _, ev := range events {
178			if ev.seq > seq {
179				break
180			}
181			payable, received = ev.afterPayable, ev.afterReceived
182		}
183		return payable, received
184	}
185	
186	// reconcileEvents 把区间内（起点之后、终点以内）涉及范围内账期的调整、
187	// 调整撤销、收款、分配更正与收款撤销合并为按全局操作序号升序的列表。
188	// 调整仅纳入所属账期在范围内的操作；收款按登记时分配、撤销按撤销时最新
189	// 分配、更正按前后分配判断是否涉及范围；终点之后的操作不提前影响结果。
190	func reconcileEvents(s *state, customerID, startMonth, endMonth string, startSeq, endSeq int64) ([]reconEvent, error) {
191		inRange := func(m string) bool { return m >= startMonth && m <= endMonth }
192		inInterval := func(seq int64) bool { return seq > startSeq && seq <= endSeq }
193	
194		var ops []reconEvent
195		for _, a := range s.Adjustments {
196			if a.CustomerID != customerID || !inRange(a.Month) {
197				continue
198			}
199			if inInterval(a.Seq) {
200				ops = append(ops, reconEvent{
201					seq: a.Seq, kind: "调整", refID: a.ID, note: a.Reason,
202					changes: []reconMonthChange{{month: a.Month, deltaPayable: a.Amount}},
203				})
204			}
205			if a.Revoked && inInterval(a.RevokeSeq) {
206				neg, err := neg64(a.Amount)
207				if err != nil {
208					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出报表", a.ID, a.Amount)
209				}
210				ops = append(ops, reconEvent{
211					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID, note: a.RevokeReason, linkSeq: a.Seq,
212					changes: []reconMonthChange{{month: a.Month, deltaPayable: neg}},
213				})
214			}
215		}
216		for _, p := range s.Payments {
217			if p.CustomerID != customerID {
218				continue
219			}
220			if inInterval(p.Seq) {
221				// 多月汇款只按范围内分配计入实收，不按汇款总额重复累加。
222				var changes []reconMonthChange
223				for _, al := range p.Allocations {
224					if inRange(al.Month) {
225						changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: al.Amount, alloc: al.Amount})
226					}
227				}
228				if len(changes) > 0 {
229					ops = append(ops, reconEvent{
230						seq: p.Seq, kind: "收款", refID: p.ID, note: p.Note, payTotal: p.Total, changes: changes,
231					})
232				}
233			}
234			// 以登记分配为起点按序号回放更正：每次更正按前后分配判断是否涉及
235			// 范围——范围内转移即使汇总变化为 0 也保留，跨范围转入或转出按
236			// 实际差额计入。
237			running := p.Allocations
238			for _, c := range correctionsFor(s, p.ID) {
239				before := running
240				running = c.Allocations
241				if !inInterval(c.Seq) {
242					continue
243				}
244				var changes []reconMonthChange
245				for _, m := range unionMonths(before, c.Allocations) {
246					if !inRange(m) {
247						continue
248					}
249					b4, af := allocAmountFor(before, m), allocAmountFor(c.Allocations, m)
250					if b4 == 0 && af == 0 {
251						continue
252					}
253					changes = append(changes, reconMonthChange{
254						month: m, deltaReceived: af - b4, beforeAlloc: b4, afterAlloc: af,
255					})
256				}
257				if len(changes) > 0 {
258					ops = append(ops, reconEvent{
259						seq: c.Seq, kind: "更正", refID: c.ID, note: c.Reason, payID: p.ID, changes: changes,
260					})
261				}
262			}
263			// 撤销取消的是撤销发生时的最新分配（更正序号均先于撤销序号，
264			// 终点之后的操作不会提前影响结果）。
265			if p.Revoked && inInterval(p.RevokeSeq) {
266				var changes []reconMonthChange
267				for _, al := range running {
268					if inRange(al.Month) {
269						changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
270					}
271				}
272				if len(changes) > 0 {
273					ops = append(ops, reconEvent{
274						seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID, note: p.RevokeReason,
275						linkSeq: p.Seq, payTotal: p.Total, changes: changes,
276					})
277				}
278			}
279		}
280		// 全局操作序号唯一，按序号排序即得到确定性的展示顺序。
281		sort.Slice(ops, func(i, j int) bool { return ops[i].seq < ops[j].seq })
282		return ops, nil
283	}
284	
285	func printReconcile(cust *customer, startMonth, endMonth string, startSeq, endSeq int64, seqDesc string, nextSeq int64,
286		bills []reconBill, sumOrig, startPaySum, startRecvSum, endPaySum, endRecvSum int128, ops []reconEvent) {
287	
288		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
289		fmt.Fprintf(stdout, "账期范围：%s 至 %s（UTC 自然月，包含首尾）\n", startMonth, endMonth)
290		fmt.Fprintf(stdout, "操作序号区间：起点 %d、终点 %d（%s）\n", startSeq, endSeq, seqDesc)
291		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
292		fmt.Fprintf(stdout, "范围内账单：%d 张（当前已存在账单，不补结算；各账单在序号 0 以原总金额为应付、零实收起算）\n", len(bills))
293	
294		if len(bills) == 0 {
295			fmt.Fprintln(stdout, "逐月余额：无（该客户在账期范围内当前没有已存在账单）")
296		} else {
297			fmt.Fprintf(stdout, "逐月余额（起点为序号 %d 完成后，终点为序号 %d 完成后）：\n", startSeq, endSeq)
298			for i, rb := range bills {
299				fmt.Fprintf(stdout, "  %d. 月份 %s：账单 %s，原总金额 %d 分（%s）\n",
300					i+1, rb.b.Month, rb.b.ID, rb.b.TotalFee, moneyFen(rb.b.TotalFee))
301				fmt.Fprintf(stdout, "     起点：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
302					rb.startPay, moneyFen(rb.startPay), rb.startRecv, moneyFen(rb.startRecv),
303					rb.startPay-rb.startRecv, moneyFen(rb.startPay-rb.startRecv))
304				fmt.Fprintf(stdout, "     终点：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
305					rb.endPay, moneyFen(rb.endPay), rb.endRecv, moneyFen(rb.endRecv),
306					rb.endPay-rb.endRecv, moneyFen(rb.endPay-rb.endRecv))
307			}
308		}
309		fmt.Fprintf(stdout, "各列汇总（%d 张账单）：\n", len(bills))
310		fmt.Fprintf(stdout, "  原总金额合计：%s 分（%s）\n", sumOrig, moneyFen128(sumOrig))
311		fmt.Fprintf(stdout, "  起点合计：应付 %s 分（%s），实收 %s 分（%s），未收余额 %s 分（%s）\n",
312			startPaySum, moneyFen128(startPaySum), startRecvSum, moneyFen128(startRecvSum),
313			startPaySum.sub(startRecvSum), moneyFen128(startPaySum.sub(startRecvSum)))
314		fmt.Fprintf(stdout, "  终点合计：应付 %s 分（%s），实收 %s 分（%s），未收余额 %s 分（%s）\n",
315			endPaySum, moneyFen128(endPaySum), endRecvSum, moneyFen128(endRecvSum),
316			endPaySum.sub(endRecvSum), moneyFen128(endPaySum.sub(endRecvSum)))
317	
318		if len(ops) == 0 {
319			fmt.Fprintf(stdout, "区间内账后操作：无（序号 %d 之后、%d 以内无涉及范围内账单的操作）\n", startSeq, endSeq)
320		} else {
321			fmt.Fprintf(stdout, "区间内账后操作（序号 %d 之后、%d 以内，按全局操作序号升序）：\n", startSeq, endSeq)
322			for i, ev := range ops {
323				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatReconEvent(ev))
324			}
325		}
326		fmt.Fprintln(stdout, "说明：逐月两端余额与相同截止序号的 bill ledger 一致；终点为存档最新序号时与 bill show 一致。")
327	}
328	
329	// formatReconEvent 渲染一条合并后的账后操作：序号、类型、记录标识、原因
330	// 或备注、撤销或更正关联、范围内各月的应付及实收变化，以及事件后的范围
331	// 内汇总余额；收款类事件同时说明汇款总额（总额不计入范围内实收）。
332	func formatReconEvent(ev reconEvent) string {
333		parts := make([]string, len(ev.changes))
334		for i, ch := range ev.changes {
335			switch ev.kind {
336			case "调整", "撤销调整":
337				parts[i] = fmt.Sprintf("%s 应付 %+d 分", ch.month, ch.deltaPayable)
338			case "收款":
339				parts[i] = fmt.Sprintf("%s 实收 %+d 分（分配 %d 分）", ch.month, ch.deltaReceived, ch.alloc)
340			case "更正":
341				parts[i] = fmt.Sprintf("%s 实收 %+d 分（分配 %d 分 → %d 分）", ch.month, ch.deltaReceived, ch.beforeAlloc, ch.afterAlloc)
342			default: // 撤销收款
343				parts[i] = fmt.Sprintf("%s 实收 %+d 分（取消分配 %d 分）", ch.month, ch.deltaReceived, ch.alloc)
344			}
345		}
346		changes := strings.Join(parts, "，")
347		after := fmt.Sprintf("事后汇总：应付 %s 分，实收 %s 分，未收余额 %s 分",
348			ev.afterPay, ev.afterRecv, ev.afterPay.sub(ev.afterRecv))
349		switch ev.kind {
350		case "调整":
351			return fmt.Sprintf("序号 %d 调整 %s：原因：%s；范围内变化：%s → %s",
352				ev.seq, ev.refID, ev.note, changes, after)
353		case "撤销调整":
354			return fmt.Sprintf("序号 %d 撤销调整 %s（关联序号 %d 的调整 %s）：原因：%s；范围内变化：%s → %s",
355				ev.seq, ev.refID, ev.linkSeq, ev.refID, ev.note, changes, after)
356		case "收款":
357			return fmt.Sprintf("序号 %d 收款 %s：备注：%s；汇款总额 %d 分（%s）；范围内变化：%s → %s",
358				ev.seq, ev.refID, ev.note, ev.payTotal, moneyFen(ev.payTotal), changes, after)
359		case "更正":
360			return fmt.Sprintf("序号 %d 更正 %s（关联收款 %s）：原因：%s；范围内变化：%s → %s",
361				ev.seq, ev.refID, ev.payID, ev.note, changes, after)
362		default: // 撤销收款
363			return fmt.Sprintf("序号 %d 撤销收款 %s（关联序号 %d 的收款 %s）：原因：%s；汇款总额 %d 分（%s）；范围内变化：%s → %s",
364				ev.seq, ev.refID, ev.linkSeq, ev.refID, ev.note, ev.payTotal, moneyFen(ev.payTotal), changes, after)
365		}
366	}
367

