// formatRemainingRefundable 以 "2026-09:200,2026-10:300（合计 500 分）" 形式
// 展示一笔收款各月剩余可退额（最新分配减该月累计退款）及合计。
func formatRemainingRefundable(s *state, p *payment) string {
